<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operation Lockdown | Live Results</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/system.css"></head>
<body><header><strong>OPERATION LOCKDOWN 2.0</strong><nav><a href="/">Mission Hub</a><span>Public leaderboard</span></nav></header>
<main class="system"><div class="eyebrow">Live Mission Control</div><h1 class="hero">Team Scoreboard</h1><p class="subtitle">Scores and recovery keys refresh automatically. Every group's score combines the best validated results submitted by its working units.</p>
<section class="system-card"><div class="row"><div><div class="muted small">Current rotation</div><h2 id="round">Round —</h2></div><div><div class="muted small">Time remaining</div><div class="timer" id="timer">--:--</div></div></div><p id="status" class="message muted"></p></section>
<section id="board" aria-live="polite"><p class="muted">Loading team results…</p></section>
<p class="note">The scoreboard shows group scores, not individual student information. Press F11 for fullscreen.</p></main>
<script type="module" src="/assets/js/leaderboard.js"></script></body></html>
